function dataPage(){return head('data',`<button class="btn" data-sys="asset-manifest">${A.icon('download')}导出资产清单</button>`)+`<div class="analytic-stats">${[['数据资产',buildAssets().length,'当前任务'],['原始媒体','1','媒体文件记录，不含原片'],['中间与分析结果','6','语义 / 标志物 / 指标 / 事件'],['报告版本','1','结构化报告 v'+(((window.__PSY_BOOT||{}).versions||{}).pipeline||A.task.version||'—')]].map(([n,v,d])=>stat(n,v,d,'database')).join('')}</div><div class="assets-layout"><section class="panel app-panel"><div class="panelhead"><h2>分析资产库</h2><span class="badge muted">${A.task.id}</span></div><div class="toolbar"><div class="filterbar">${[['全部','all'],['原始媒体','media'],['语义数据','semantic'],['标志物','markers'],['分析结果','results'],['报告','reports']].map(([n,k],i)=>`<button class="chip ${i===0?'active':''}" data-asset-type="${k}">${n}</button>`).join('')}</div><div class="inline-search">${A.icon('search')}<input id="asset-search" placeholder="搜索文件、编号或生成阶段" aria-label="搜索数据资产"></div></div><div class="tablewrap"><table class="sys-table"><thead><tr><th>名称 / 来源任务</th><th>大小 / 时间范围</th><th>完整性 / 生成阶段</th><th>操作</th></tr></thead><tbody id="asset-table">${assetRows(buildAssets())}</tbody></table></div><div class="tablebottom"><span id="asset-count">${buildAssets().length} 条资产记录</span><a class="tablelink" href="logs.html">原始数据与日志 ↗</a></div></section><aside class="home-aside"><section class="panel app-panel"><div class="panelhead"><h2>资产详情</h2><span class="badge muted">来源追溯</span></div><div id="asset-inspector">${assetInspector(buildAssets()[0])}</div></section><section class="panel app-panel"><div class="panelhead"><h2>本地存储概览</h2><span class="badge muted">未接入</span></div><div class="statnumber" style="color:#6580a3">— <small>可用磁盘空间</small></div><div class="notice">网页无法直接查询系统模型目录或分析数据库容量。资产清单来自当前任务；磁盘监控由本地服务提供。</div><div class="source-row"><a class="tablelink" href="settings.html?tab=storage">数据存储设置 ↗</a></div></section></aside></div>`}
