let selectedFile=null,fileMeta=null,singleURL=null,batchFiles=[],batchCreated=0,keywords=['压力','时间'],taskFilter='all',assetFilter='all',viewerCategory='media',eventView='list',stream=null,recorder=null,recordChunks=[],recordBlob=null,recordURL=null,recordSeconds=0,recordLast=0,recordTimer=null,currentSetting='general';
async function probe(file){return new Promise(resolve=>{const video=document.createElement('video'),url=URL.createObjectURL(file);let timer;const finish=(ok,reason)=>{clearTimeout(timer);let audio='待解码器检查';try{if(video.audioTracks)audio=video.audioTracks.length?'存在音轨':'未检测到音轨';else if(typeof video.mozHasAudio==='boolean')audio=video.mozHasAudio?'存在音轨':'未检测到音轨'}catch{}const result={name:file.name,size:file.size,mime:file.type||'未知',duration:Number.isFinite(video.duration)?video.duration:0,width:video.videoWidth||0,height:video.videoHeight||0,audio,readable:ok,error:reason||'',lastModified:file.lastModified};video.removeAttribute('src');video.load();URL.revokeObjectURL(url);resolve(result)};video.preload='metadata';video.onloadedmetadata=()=>finish(video.videoWidth>0,video.videoWidth?'':'未读取到视频画面');video.onerror=()=>finish(false,'浏览器无法解码该视频');video.src=url;timer=setTimeout(()=>finish(false,'读取超时，请检查文件编码'),12000)})}
function configForm(){return {name:$('#task-name')?.value.trim()||selectedFile?.name||'',subject:$('#subject')?.value.trim()||'',scene:$('#scene')?.value||'科研访谈',output:$('#output')?.value||'full',notes:$('#notes')?.value.trim()||'',topics:$$('[name="focus-topic"]:checked').map(x=>x.value),keywords:[...keywords],rulesVersion:'local-configuration-v1'}}
function newTask(meta,config,source='单视频'){const id='PT-20261021-L'+Date.now().toString(36).toUpperCase()+Math.random().toString(36).slice(2,4).toUpperCase();return {id,name:config.name||meta.name,subject:config.subject,file:meta.name,source,duration:meta.duration||0,size:meta.size||0,resolution:meta.width?meta.width+' × '+meta.height:'待检查',created:now().slice(0,16),status:'queued',stage:0,demo:false,config:{...config,activeRules:store.rules.filter(r=>r.enabled).map(r=>({...r})),thresholdsByMarker:store.thresholdsByMarker||{},configurationVersion:'local-v1'},mediaStored:false}}
function taskCreated(list){store.tasks.unshift(...list);audit('创建分析任务',list.map(t=>t.id).join(', '));A.openModal('任务已创建',`<p class="modaldesc">已创建 ${list.length} 个分析任务，视频已上传并进入解析队列。</p>${list.map(t=>`<div class="report-tile"><div class="report-glyph">${A.icon('video')}</div><div><h3>${h(t.name)}</h3><p>${h(t.id)} · ${h(t.subject)}</p></div></div>`).join('')}<div class="notice">视频已上传到本地分析服务，分析完成后可在任务中心查看画像与报告。</div><div class="modalactions"><button class="btn" data-sys="task-manifest">导出任务清单</button><a class="btn primary" href="${route('tasks',{task:list[0].id})}">查看任务阶段 ${A.icon('arrow')}</a></div>`)}
async function selectSingle(file){if(!file)return;selectedFile=file;fileMeta=null;$('#selected-file-name').textContent='正在检查 '+file.name;$('#file-state').textContent='读取中';const meta=await probe(file);if(selectedFile!==file)return;fileMeta=meta;$('#selected-file-name').textContent=file.name+' · '+bytes(file.size);$('#file-state').textContent=meta.readable?'元数据已读取':'需检查';$('#file-state').className='badge '+(meta.readable?'green':'amber');if(singleURL)URL.revokeObjectURL(singleURL);singleURL=URL.createObjectURL(file);const video=$('#input-preview');video.src=singleURL;video.hidden=!meta.readable;$('#preview-caption').hidden=meta.readable;$('#file-meta').innerHTML=[['文件名称',file.name],['格式 / 大小',(file.type||'未知')+' / '+bytes(file.size)],['时长',meta.duration?A.fmt(meta.duration):'未读取'],['分辨率',meta.width?meta.width+' × '+meta.height:'未读取']].map(([n,v])=>`<div><span>${n}</span><b>${h(v)}</b></div>`).join('');$('#file-checks').innerHTML=`<div class="check-row ${meta.readable?'pass':'warn'}">${A.icon(meta.readable?'check':'warning')}<span>视频文件可读取</span><span>${meta.readable?'通过':'失败'}</span></div><div class="check-row ${meta.width?'pass':'warn'}">${A.icon(meta.width?'check':'warning')}<span>视觉画面可解析</span><span>${meta.width?'通过':'需检查'}</span></div><div class="check-row">${A.icon('pulse')}<span>音轨状态</span><span>${h(meta.audio)}</span></div><div class="check-row">${A.icon('clock')}<span>帧率</span><span>浏览器未提供</span></div><div class="check-row warn">${A.icon('warning')}<span>模型与存储服务</span><span>待连接</span></div>`;if(!$('#task-name').value)$('#task-name').value=file.name.replace(/\.[^.]+$/,'');$$('[data-step]').forEach((e,i)=>{e.classList.toggle('complete',i===0&&meta.readable);e.classList.toggle('active',i===1)});if(!meta.readable)A.toast(meta.error||'文件暂时无法读取');}
function renderKeywords(){if(!$('#keyword-editor'))return;$$('.keytag',$('#keyword-editor')).forEach(e=>e.remove());keywords.forEach((k,i)=>{const el=document.createElement('span');el.className='keytag';el.innerHTML=`${h(k)}<button type="button" data-sys="keyword-remove" data-index="${i}" aria-label="移除关键词 ${h(k)}">×</button>`;$('#keyword-editor').insertBefore(el,$('#keyword-input'))})}
async function addBatch(files){for(const file of files){const key=file.name+'|'+file.size+'|'+file.lastModified;const duplicate=batchFiles.some(f=>f.key===key);const entry={key,file,subject:'',state:duplicate?'duplicate':'reading',meta:null,created:false};batchFiles.push(entry);renderBatch();if(duplicate)continue;entry.meta=await probe(file);entry.state=entry.meta.readable?'valid':'invalid';renderBatch()}}
function renderBatch(){if(!$('#batch-table'))return;$('#batch-table').innerHTML=batchFiles.length?batchFiles.map((b,i)=>`<tr><td><div class="rowtitle">${h(b.file.name)}</div><div class="rowsub">${bytes(b.file.size)} · ${h(b.file.type||'未知格式')}</div></td><td>${b.meta?.duration?A.fmt(b.meta.duration):'—'}<div class="rowsub"><span class="badge ${b.state==='valid'?'green':['duplicate','invalid'].includes(b.state)?'amber':'muted'}">${{reading:'校验中',valid:'通过',invalid:'失败',duplicate:'重复文件'}[b.state]}${b.created?' / 已登记':''}</span></div></td><td><input class="sys-input" data-batch-subject="${i}" value="${h(b.subject)}" aria-label="${h(b.file.name)}的受试者编号" placeholder="P-编号" style="margin:0;width:100px;font-size:10px" maxlength="40"></td><td style="font-size:9px">${h(b.state==='duplicate'?'名称、大小与修改时间重复':b.state==='reading'?'正在读取元数据':b.meta?.error||'可读；音轨待服务检查')}</td><td><button class="tablelink" data-sys="batch-remove" data-index="${i}">移除</button></td></tr>`).join(''):`<tr><td colspan="5">${empty('尚未添加历史视频')}</td></tr>`;const valid=batchFiles.filter(f=>f.state==='valid').length,errors=batchFiles.filter(f=>['duplicate','invalid'].includes(f.state)).length;$('#batch-stats').innerHTML=[['文件总数',batchFiles.length],['校验通过',valid],['需检查 / 重复',errors],['已创建任务',batchCreated]].map(([n,v])=>stat(n,v,'当前导入批次','file')).join('');$('#batch-summary').textContent=`${valid} 个文件通过元数据校验 · ${batchCreated} 个已登记`;}
function filterTasks(){const query=$('#task-search')?.value.trim().toLowerCase()||'';let list=allTasks().filter(t=>(taskFilter==='all'||taskFilter==='review'&&t.review||taskFilter==='failed'&&t.status==='failed'||t.status===taskFilter)&&[t.id,t.name,t.subject,t.file].join(' ').toLowerCase().includes(query));if($('#task-table'))$('#task-table').innerHTML=taskRows(list,P==='index');if($('#task-count'))$('#task-count').textContent=`${list.length} 条匹配记录 / 共 ${allTasks().length} 个任务`;$$('[data-task-filter]').forEach(b=>b.classList.toggle('active',b.dataset.taskFilter===taskFilter))}
function filterAssets(){const q=$('#asset-search')?.value.trim().toLowerCase()||'';const all=buildAssets();const list=all.filter(a=>(assetFilter==='all'||a.type===assetFilter)&&[a.name,a.id,a.stage,A.task.id].join(' ').toLowerCase().includes(q));$('#asset-table').innerHTML=assetRows(list);$('#asset-count').textContent=list.length+' 条匹配资产 / 共 '+all.length+' 条'}
function rawObject(category){const common={task_id:A.task.id,source:'portrait'};const boot=window.__PSY_BOOT||{};const cov=boot.coverage||{};const vers=boot.versions||{};const dur=Math.max(1,A.task.duration||boot.duration||1);const alertList=boot.alerts||[];return {media:{...common,data_id:'AS-001',file:A.task.file,duration_s:dur,format:'mp4',media_attached:Boolean(A.task.video_url),stage:'original_input'},transcript:A.transcript.map((t,i)=>({...common,data_id:'TXT-'+(i+1),timestamp_s:t.time,topic:t.topic,text:t.text,stage:'transcription'})),topics:A.topics.map((t,i)=>({...common,topic_id:'TOP-'+(i+1),...t,stage:'topic_classification'})),markers:A.markerData.map((m,i)=>({...common,marker_id:'BM-'+i,name:m.name,unit:m.unit,baseline:A.baseMarker[i],samples:A.markerCurve(i).map((v,j)=>({timestamp_s:Number((j*dur/Math.max(1,A.markerCurve(i).length-1)).toFixed(2)),value:Number(v.toFixed(3)),valid:true})),stage:'biomarker_extraction'})),alignment:{...common,baseline_scope:'within_task_valid_intervals',design_grid_ms:vers.grid_ms||100,topics:A.topics,stage:'alignment'},indicators:{...common,type:'model_computation',categories:A.metrics.map(({values,...m})=>m),extended:A.extended,stage:'indicator_calculation'},events:A.events.map(e=>({...common,...e,review:store.reviews[e.id]||null,stage:'special_content'})),alerts:alertList.map(a=>({...common,...a,stage:'change_detection'})),config:A.logData,logs:{...common,processing_stages:stages,model_versions:A.logData.models||vers,errors:[],coverage:cov},quality:{...common,face_detected_rate:cov.face_detected_rate??null,pose_detected_rate:cov.pose_detected_rate??null,speech_time_rate:cov.speech_time_rate??null,asr_char_count:cov.asr_char_count??null,missing_intervals:[]},report:{...common,report_id:'RP-'+A.task.id,version:vers.pipeline||A.task.version||'—',created:A.task.completed||A.task.created||null,versions:vers,task:A.task}}[category]}
function renderViewer(category){viewerCategory=categories.some(([k])=>k===category)?category:'media';if(!$('#raw-data-content'))return;$('#raw-data-content').textContent=JSON.stringify(rawObject(viewerCategory),null,2);$$('.data-category').forEach(b=>b.classList.toggle('active',b.dataset.category===viewerCategory));}
function renderComparison(){if(!$('#marker-comparison'))return;const dur=Math.max(1,A.task.duration||1);const selected=$$('[data-compare-marker]:checked').map(e=>Number(e.dataset.compareMarker));$('#marker-comparison').innerHTML=selected.map(i=>{const m=A.markerData[i],curve=A.markerCurve(i);return `<div class="comparison-panel"><h4>${m.name} <span style="color:#5878a1">/ ${m.unit}</span></h4>${A.spark(curve,i%2?'#77a9ca':'#929eeb','compare'+i)}<p>基线 ${m.base} · 独立量纲 · <a class="tablelink" href="markers.html?marker=${i}&t=0">查看单特征 ↗</a></p></div>`}).join('');$('#marker-sample-table').innerHTML=selected.flatMap(i=>{const curve=A.markerCurve(i);const n=Math.max(1,curve.length-1);return [0,5,14].filter(j=>j<curve.length).map(j=>`<tr><td class="mono">${A.fmt(j*dur/n)}</td><td>${A.markerData[i].name}</td><td>${curve[j].toFixed(2)} ${A.markerData[i].unit}</td><td>任务观测</td><td><button class="tablelink" data-seek="${Math.round(j*dur/n)}">回看 ↗</button></td></tr>`)}).join('')}
function renderAlertFilter(){if(!$('#alert-filter-results'))return;const q=$('#alert-search').value.toLowerCase(),topic=$('#alert-topic').value,status=$('#alert-review').value;const bootAlerts=(window.__PSY_BOOT||{}).alerts||[];const list=(bootAlerts.length?bootAlerts:A.events).filter(e=>(topic==='all'||e.topic===topic||!e.topic)&&(status==='all'||(status==='reviewed')===!!e.reviewed)&&[e.id,e.key,e.marker,e.topic,e.text,e.level].join(' ').toLowerCase().includes(q));$('#alert-filter-results').innerHTML=list.length?list.map(e=>{const t=e.time!=null?e.time:Math.round((e.start_ms||0)/1000);return `<button class="finding" data-seek="${t}"><span class="findicon amber">${A.icon('bolt')}</span><div class="findingbody"><div class="findingtitle">${e.id||'ALERT'} · ${e.level||e.marker||'突变'}</div><div class="findingdesc">${e.time_label||A.fmt(t)} · ${h(e.text||e.marker||'—')}</div></div><span class="time">${e.time_label||A.fmt(t)}</span>${A.icon('arrow')}</button>`}).join(''):empty('没有符合筛选条件的预警')}
function renderEventView(){if(!$('#event-view-content'))return;const list=A.events;$('#event-view-content').innerHTML=eventView==='topic'?['工作','健康'].map(topic=>`<div class="event-group-label">${topic}主题 · ${list.filter(e=>e.topic===topic).length} 条</div>${list.filter(e=>e.topic===topic).map(e=>`<button class="finding" data-event="${e.id}"><div class="findingbody"><div class="findingtitle">${e.id} · ${e.title}</div><div class="findingdesc">${e.type} / ${e.marker}</div></div><time class="time">${A.fmt(e.time)}</time>${A.icon('arrow')}</button>`).join('')}`).join(''):eventView==='timeline'?eventTimeline(list):`<div class="tablewrap"><table class="sys-table"><thead><tr><th>事件 / 时间</th><th>触发 / 主题</th><th>关键词 / 特征</th><th>复核</th></tr></thead><tbody>${list.map(e=>`<tr><td>${e.id}<div class="rowsub">${A.fmt(e.time)}–${A.fmt(e.end)}</div></td><td>${e.type}<div class="rowsub">${e.topic}</div></td><td>${e.key}<div class="rowsub">${e.marker}</div></td><td><button class="tablelink" data-event="${e.id}">${h(store.reviews[e.id]?.outcome||(e.reviewed?'已复核':'待复核'))} ↗</button></td></tr>`).join('')}</tbody></table></div>`}
function reviewFields(){if($('#modalback')?.hidden||$('#modal-title')?.textContent!=='特殊内容 · 三层对比'||$('#review-form'))return;const id=$('.modaldesc',$('#modal-body'))?.textContent.match(/EV-\d+/)?.[0];if(!id)return;const e=A.events.find(e=>e.id===id);const saved=store.reviews[id]||{};const form=document.createElement('div');form.className='review-form';form.id='review-form';form.innerHTML=`<label>人工复核备注<textarea id="review-note" maxlength="1000" placeholder="填写观测依据、数据质量或需要进一步检查的内容">${h(saved.note||'')}</textarea></label><label style="margin-top:10px">处理状态<select id="review-outcome">${['待复核','已复核','数据不足','需进一步检查'].map(n=>`<option ${n===(saved.outcome||(e.reviewed?'已复核':'待复核'))?'selected':''}>${n}</option>`).join('')}</select></label><button class="btn primary" data-sys="save-review" data-id="${id}">${A.icon('check')}保存复核记录</button>${saved.time?`<div class="subtle-note">最近更新 ${h(saved.time)}</div>`:''}`;const actions=$('.modalactions',$('#modal-body'));if(actions)actions.before(form);else $('#modal-body').append(form);const old=$('[data-review]',$('#modal-body'));if(old)old.hidden=true;const compare=$('.comparison',$('#modal-body'));if(compare&&A.transcript.filter(t=>t.text.includes(e.key)).length<2){const box=compare.children[2];box.innerHTML=`<small>03 · 同类词其他出现</small><b style="font-size:16px">样本不足</b><span>当前转写文本中缺少可比较重复词项</span>`}}
