function ruleDialog(id){const rule=store.rules.find(r=>r.id===id)||{id:'',name:'',words:'',topic:'工作',trigger:'组合触发',enabled:true};A.openModal(rule.id?'编辑关注词规则':'新增关注词规则',`<p class="modaldesc">规则保存在当前浏览器，对后续登记的任务配置生效。</p><div class="formfields"><label class="form-field full">规则名称<input id="rule-name" value="${h(rule.name)}" maxlength="60"></label><label class="form-field full">关键词（使用顿号或逗号分隔）<input id="rule-words" value="${h(rule.words)}" maxlength="250"></label><label class="form-field">关联主题<select id="rule-topic">${['健康','家庭','工作','经济','情感','法律','创伤','自我评价','其他'].map(n=>`<option ${n===rule.topic?'selected':''}>${n}</option>`).join('')}</select></label><label class="form-field">触发方式<select id="rule-trigger">${['关键词触发','标志物异常','组合触发'].map(n=>`<option ${n===rule.trigger?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="modalactions"><button class="btn" data-action="close">取消</button><button class="btn primary" data-sys="rule-save" data-id="${h(rule.id)}">保存规则</button></div>`)}
